-- +goose Up

-- Conventions
--   ids        bigint snowflakes generated by the server (time-ordered, unique across tables)
--   enums      smallint; the names live in internal/domain/enums.go
--   status     negative is terminal, 0 is initial or pending, positive is alive
--   who        *_kind smallint (1 user, 2 agent) + *_id bigint; names are never stored.
--              Each kind is checked to be 1 or 2, and an optional pair is null
--              or set as a whole. A column that can only name a user is a
--              plain *_user_id with no kind.
--   no foreign keys: the service writes related rows in one transaction
--   org_id     only on tables that are queried by org without going through a parent

CREATE TABLE orgs (
    id                   bigint PRIMARY KEY,
    name                 text NOT NULL,
    status               smallint NOT NULL,   -- 10 active, 0 created, -5 suspended, -10 deleted
    settings             jsonb NOT NULL,    -- read and written whole, never filtered on
    created_at           timestamptz NOT NULL,
    updated_at           timestamptz NOT NULL
);

CREATE TABLE users (
    id         bigint PRIMARY KEY,
    login      text NOT NULL,
    name       text NOT NULL,
    email      text NOT NULL,
    avatar_url text NOT NULL,
    locale     text,               -- BCP 47, null until the user sets one
    timezone   text,               -- IANA, null until the user sets one
    status     smallint NOT NULL,    -- 10 active, -5 suspended, -10 deleted
    agent_join smallint NOT NULL,    -- 0 follow (off), 10 allow: the user's agents join their projects without asking
    created_at timestamptz NOT NULL,
    updated_at timestamptz NOT NULL
);

-- One row per way a user can log in. The bootstrap user starts with a
-- password identity; a GitHub login later adds a second row.
CREATE TABLE identities (
    id            bigint PRIMARY KEY,
    user_id       bigint NOT NULL,
    provider      smallint NOT NULL,             -- 1 github, 2 password, 3 google, 4 microsoft, 5 passkey
    provider_id   text NOT NULL,                 -- github numeric id; lowercased email; passkey credential id
    secret        bytea,                         -- argon2id hash, passkey public key; null for OAuth
    login         text NOT NULL,
    last_login_at timestamptz,
    created_at    timestamptz NOT NULL
);
CREATE UNIQUE INDEX identities_provider_key ON identities (provider, provider_id);
CREATE INDEX identities_user_idx ON identities (user_id);

-- Org-level role of a user or an agent. An agent with a row here is org-wide.
CREATE TABLE memberships (
    org_id     bigint NOT NULL,
    actor_kind smallint NOT NULL CHECK (actor_kind IN (1, 2)),
    actor_id   bigint NOT NULL,
    role       smallint NOT NULL,                -- 10 viewer, 20 member, 30 reviewer, 40 admin, 50 owner
    status     smallint NOT NULL,     -- 10 active, 0 invited or pending approval, -10 removed
    rights     smallint NOT NULL,                -- an agent's rights, a bitmask: 1 work, 2 ready, 4 triage, 8 answer, 16 decide; 0 for people
    granted_by_user_id bigint,                   -- null for the bootstrap owner and for a request made by signing in with GitHub
    created_at timestamptz NOT NULL,
    updated_at timestamptz NOT NULL,
    PRIMARY KEY (org_id, actor_kind, actor_id)
);
CREATE INDEX memberships_actor_idx ON memberships (actor_kind, actor_id) WHERE status >= 0;

CREATE TABLE agents (
    id         bigint PRIMARY KEY,
    org_id     bigint NOT NULL,
    name       text NOT NULL,
    harness    smallint NOT NULL,      -- 0 other, 1 claude-code, 2 codex, 3 opencode, 4 gemini-cli, 5 copilot-cli, 6 cursor, 7 pi, 8 qwen, 9 dsh, 10 goose
    machine    text NOT NULL,
    created_by_user_id bigint NOT NULL,          -- the owner: the agent acts only within this user's current rights
    status     smallint NOT NULL,     -- 10 active, 0 pending approval, -10 revoked (can be restored), -20 removed for good
    agent_join smallint NOT NULL,     -- 0 follow, 10 allow in all the owner's projects, 20 always ask
    created_at timestamptz NOT NULL,
    updated_at timestamptz NOT NULL
);
CREATE INDEX agents_org_idx ON agents (org_id, status, created_at);
-- A name is unique among the org's pending and active agents; a revoked or
-- removed agent frees its name.
CREATE UNIQUE INDEX agents_name_key ON agents (org_id, name) WHERE status >= 0;

CREATE TABLE tokens (
    id           bigint PRIMARY KEY,
    org_id       bigint NOT NULL,                -- 0 for a sign-in token, which belongs to a person and to no org
    actor_kind   smallint NOT NULL CHECK (actor_kind IN (1, 2)),
    actor_id     bigint NOT NULL,
    name         text NOT NULL,
    prefix       text NOT NULL,                  -- first 12 chars of the secret, for lists
    hash         bytea NOT NULL,                 -- SHA3-384 of the secret, 48 bytes
    scope        smallint NOT NULL,   -- 5 sign-in (choose or create an org, nothing else), 10 read only, 20 act as the actor
    status       smallint NOT NULL,   -- 10 active, 5 rotated (in grace), -10 revoked
    expires_at   timestamptz NOT NULL,
    replaced_by  bigint,                         -- successor token after rotation
    last_used_at timestamptz,
    created_at   timestamptz NOT NULL
);
CREATE UNIQUE INDEX tokens_hash_key ON tokens (hash);
CREATE INDEX tokens_actor_idx ON tokens (org_id, actor_id, created_at DESC);

CREATE TABLE projects (
    id                   bigint PRIMARY KEY,
    org_id               bigint NOT NULL,
    slug                 text NOT NULL,
    name                 text NOT NULL,
    description          text NOT NULL,
    visibility           smallint NOT NULL,   -- 10 org, 20 private
    concurrency          smallint NOT NULL,   -- 10 parallel, 20 serial
    scope                smallint NOT NULL,   -- 1 project, 2 global (exactly one global project per org)
    lease_seconds        integer NOT NULL,
    next_card_number     bigint NOT NULL,
    created_by_kind      smallint NOT NULL CHECK (created_by_kind IN (1, 2)),
    created_by_id        bigint NOT NULL,
    status               smallint NOT NULL,   -- 10 active, -10 archived
    agent_join           smallint NOT NULL,   -- 0 follow, 20 agents always ask here (set by a project admin)
    created_at           timestamptz NOT NULL,
    updated_at           timestamptz NOT NULL
);
CREATE UNIQUE INDEX projects_slug_key ON projects (org_id, slug);
CREATE UNIQUE INDEX projects_global_key ON projects (org_id) WHERE scope = 2;

-- Project-level role of a user or an agent. Same scale as memberships;
-- admin and owner are org roles and never appear here. An agent's request
-- to join is a pending row whose granted_by_user_id is the agent's owner,
-- the one who decides it.
CREATE TABLE project_members (
    project_id bigint NOT NULL,
    actor_kind smallint NOT NULL CHECK (actor_kind IN (1, 2)),
    actor_id   bigint NOT NULL,
    role       smallint NOT NULL,
    status     smallint NOT NULL,     -- 10 active, 0 requested by an agent, -10 removed or denied
    rights     smallint NOT NULL,                -- an agent's rights, a bitmask: 1 work, 2 ready, 4 triage, 8 answer, 16 decide; 0 for people
    granted_by_user_id bigint,                   -- the user who granted the role
    created_at timestamptz NOT NULL,
    updated_at timestamptz NOT NULL,
    PRIMARY KEY (project_id, actor_kind, actor_id)
);
CREATE INDEX project_members_actor_idx ON project_members (actor_kind, actor_id) WHERE status > 0;
CREATE INDEX project_members_requests_idx ON project_members (granted_by_user_id) WHERE status = 0;

-- A user's own say over their agents joining one project. No row is follow.
CREATE TABLE agent_join_rules (
    project_id bigint NOT NULL,
    user_id    bigint NOT NULL,
    agent_join smallint NOT NULL,     -- 10 allow, 20 always ask
    updated_at timestamptz NOT NULL,
    PRIMARY KEY (project_id, user_id)
);

-- The chats seen using an agent's token, so the owner can grant one of them
-- rights. session is a base label: subagent suffixes (-c<n>) are stripped.
CREATE TABLE agent_sessions (
    agent_id     bigint NOT NULL,
    session      text NOT NULL,
    name         text,                 -- what people call the chat, shown beside the label; null when it has none, never ''
    created_at   timestamptz NOT NULL,
    last_seen_at timestamptz NOT NULL,
    PRIMARY KEY (agent_id, session)
);

-- Rights the owner gave one session of an agent in one project, on top of
-- the agent's own rights there.
CREATE TABLE agent_session_grants (
    project_id bigint NOT NULL,
    agent_id   bigint NOT NULL,
    session    text NOT NULL,         -- a base label
    rights     smallint NOT NULL,     -- bitmask: 1 work, 2 ready, 4 triage, 8 answer, 16 decide
    granted_by_user_id bigint NOT NULL,
    ends_at    timestamptz,           -- the grant gives nothing from then on; null: until taken back
    instructions text,                -- the owner's words to the chat; null for none
    status     smallint NOT NULL,     -- 10 active, -10 removed
    created_at timestamptz NOT NULL,
    updated_at timestamptz NOT NULL,
    PRIMARY KEY (project_id, agent_id, session)
);
CREATE INDEX agent_session_grants_agent_idx ON agent_session_grants (agent_id) WHERE status > 0;
CREATE INDEX agent_session_grants_ends_idx ON agent_session_grants (ends_at) WHERE status > 0 AND ends_at IS NOT NULL;

-- Fixed-width columns first, text last, to avoid alignment padding.
CREATE TABLE cards (
    id               bigint PRIMARY KEY,
    org_id           bigint NOT NULL,             -- org-wide search
    project_id       bigint NOT NULL,
    number           bigint NOT NULL,
    parent_id        bigint,
    kind             smallint NOT NULL,           -- 1 task, 2 question, 3 story, 4 decision
    status           smallint NOT NULL, -- -20 dropped, -10 done, 0 backlog, 5 ready, 7 waiting, 10 working
    drop_reason      smallint,                    -- 1 obsolete, 2 duplicate, 3 wontfix, 4 rejected, 5 revoked, 6 superseded (4 to 6 only on decisions); set iff dropped
    priority         smallint NOT NULL, -- 0 low, 1 normal, 2 high, 3 urgent
    created_by_kind  smallint NOT NULL CHECK (created_by_kind IN (1, 2)),
    created_by_id    bigint NOT NULL,
    assignee_kind    smallint,
    assignee_id      bigint,
    answer_relayed   boolean NOT NULL,            -- a question's answer an agent passed on and no person has confirmed
    for_person       boolean NOT NULL,            -- a question only a person may answer; an agent still relays
    answered_by_kind smallint,
    answered_by_id   bigint,
    answered_at      timestamptz,           -- for a decision, who accepted it and when
    behalf_user_id   bigint,                -- the person an agent settled the card for under a right they gave it; null when a person settled it
    behalf_agent_id  bigint,                -- the agent that settled it; set iff behalf_user_id is
    behalf_kept_at   timestamptz,           -- when that person kept it; null: not looked at
    closed_at        timestamptz,
    folded_by_kind   smallint,
    folded_by_id     bigint,
    folded_at        timestamptz,           -- null until folded into the requirements documents
    version          bigint NOT NULL,   -- optimistic concurrency
    page_bytes       integer NOT NULL,            -- size of the card's page in card_pages; 0 when it has none
    created_at       timestamptz NOT NULL,
    updated_at       timestamptz NOT NULL,
    title            text NOT NULL,
    body             text NOT NULL,
    question_choices text[] NOT NULL,
    answer           text,
    behalf_reason    text,                        -- what the agent said it relied on; set iff behalf_user_id is
    behalf_session   text,                        -- the chat the agent acted from
    branch           text,                        -- git branch the work is on
    lane             text,                        -- mutual-exclusion tag; one working card per lane
    folded_into      text,                        -- document path the card was folded into; empty string = folded with no document; null until folded
    closing_note     text,                        -- the note given when the card was last done or dropped; null while open
    CHECK (assignee_kind IN (1, 2) AND (assignee_kind IS NULL) = (assignee_id IS NULL)),
    CHECK (answered_by_kind IN (1, 2) AND (answered_by_kind IS NULL) = (answered_by_id IS NULL)),
    CHECK (folded_by_kind IN (1, 2) AND (folded_by_kind IS NULL) = (folded_by_id IS NULL))
);
CREATE UNIQUE INDEX cards_number_key ON cards (project_id, number);
CREATE INDEX cards_board_idx  ON cards (project_id, status, priority DESC, number);
-- What an agent settled for a person and that person has not kept yet.
CREATE INDEX cards_behalf_idx ON cards (behalf_user_id) WHERE behalf_user_id IS NOT NULL AND behalf_kept_at IS NULL;
-- The sorted list orders (sort=created, updated, priority); each index also
-- serves its order reversed. sort=number uses cards_number_key.
CREATE INDEX cards_created_idx  ON cards (project_id, created_at, number);
CREATE INDEX cards_updated_idx  ON cards (project_id, updated_at, number);
CREATE INDEX cards_priority_idx ON cards (project_id, priority, number);
CREATE INDEX cards_parent_idx ON cards (parent_id) WHERE parent_id IS NOT NULL;
-- Safety net for the unfolded list: done cards with no parent and no fold mark.
CREATE INDEX cards_unfolded_idx ON cards (project_id, closed_at DESC, id DESC) WHERE status = -10 AND parent_id IS NULL AND folded_at IS NULL;
CREATE INDEX cards_search_idx ON cards USING gin (to_tsvector('english', title || ' ' || body));

-- The HTML page of a card (up to 1 MiB) and its visible text for search. It
-- is a separate table because lists select whole card rows and must not carry
-- pages; only the page route, revisions and search read it. A card without a
-- page has no row and page_bytes 0.
CREATE TABLE card_pages (
    card_id bigint PRIMARY KEY,
    html    text NOT NULL,
    text    text NOT NULL                         -- visible text, at most 256 KiB (tsvector size limit)
);
CREATE INDEX card_pages_search_idx ON card_pages USING gin (to_tsvector('english', text));

-- One row per live claim. Renewals update expires_at only; with no index on
-- it the update is heap-only. The sweeper scans the whole table, which holds
-- only live claims.
CREATE TABLE claims (
    card_id    bigint PRIMARY KEY,
    org_id     bigint NOT NULL,
    project_id bigint NOT NULL,
    actor_kind smallint NOT NULL CHECK (actor_kind IN (1, 2)),
    actor_id   bigint NOT NULL,
    session    text NOT NULL,
    expires_at timestamptz NOT NULL,
    created_at timestamptz NOT NULL,
    lease_seconds integer,           -- the length the holder stated for this claim; null follows the project's lease
    ending_announced_for timestamptz -- the expires_at the last call was written for; null when none was
);
CREATE INDEX claims_actor_idx ON claims (org_id, actor_kind, actor_id);

-- A chat subscribed to a card: an event on the card wakes the chat, which is how
-- a chat that left a card waiting on a person hears their reply. session is
-- a base label, so a chat's subagents share its subscriptions. There is no unique
-- index: a subscription is added only where none exists, and a rare duplicate from
-- two concurrent calls is harmless, since unsubscribing deletes every match and
-- reads de-duplicate. The sweeper deletes the subscriptions of chats unseen for a
-- day and of cards done or dropped more than an hour ago.
CREATE TABLE card_subscriptions (
    org_id     bigint NOT NULL,
    card_id    bigint NOT NULL,
    agent_id   bigint NOT NULL,
    session    text NOT NULL,
    created_at timestamptz NOT NULL
);
CREATE INDEX card_subscriptions_chat_idx ON card_subscriptions (agent_id, session);
CREATE INDEX card_subscriptions_card_idx ON card_subscriptions (card_id);

-- Named locks on shared resources, one row per name. An expired row stays
-- until the sweeper deletes it or the next acquire takes it over in place.
-- Renewal is explicit, so no request touches expires_at but the renew call.
CREATE TABLE locks (
    id          bigint PRIMARY KEY,
    org_id      bigint NOT NULL,
    holder_kind smallint NOT NULL CHECK (holder_kind IN (1, 2)),
    holder_id   bigint NOT NULL,
    card_id     bigint,                   -- the card the holder works on, when named
    acquired_at timestamptz NOT NULL,
    expires_at  timestamptz NOT NULL,
    name        text NOT NULL,            -- 1 to 40 of a-z 0-9 - /
    session     text NOT NULL,            -- empty when the client sent none
    purpose     text NOT NULL
);
CREATE UNIQUE INDEX locks_name_key ON locks (org_id, name);

CREATE TABLE card_links (
    from_card_id    bigint NOT NULL,
    to_card_id      bigint NOT NULL,
    kind            smallint NOT NULL,            -- 1 blocks, 2 relates, 3 duplicates, 4 supersedes, 5 applies
    created_by_kind smallint NOT NULL CHECK (created_by_kind IN (1, 2)),
    created_by_id   bigint NOT NULL,
    created_at      timestamptz NOT NULL,
    PRIMARY KEY (from_card_id, to_card_id, kind)
);
CREATE INDEX card_links_to_idx ON card_links (to_card_id, kind);

-- Append-only. The id carries the time; (card_id, id DESC) gives the latest.
CREATE TABLE comments (
    id         bigint PRIMARY KEY,
    card_id    bigint NOT NULL,
    actor_kind smallint NOT NULL CHECK (actor_kind IN (1, 2)),
    actor_id   bigint NOT NULL,
    body       text NOT NULL
);
CREATE INDEX comments_card_idx ON comments (card_id, id DESC);

-- One row per actor and card the actor has written on or opened. seen_id is a
-- snowflake id minted at that moment, so a comment is unseen when its id is
-- greater; ids are time-ordered.
CREATE TABLE card_reads (
    card_id    bigint NOT NULL,
    project_id bigint NOT NULL,
    actor_kind smallint NOT NULL CHECK (actor_kind IN (1, 2)),
    actor_id   bigint NOT NULL,
    seen_id    bigint NOT NULL,
    PRIMARY KEY (actor_kind, actor_id, card_id)
);
CREATE INDEX card_reads_project_idx ON card_reads (actor_kind, actor_id, project_id);

-- Keys never expire: a write can wait in a client's queue for any length of time.
CREATE TABLE request_keys (
    actor_kind smallint NOT NULL CHECK (actor_kind IN (1, 2)),
    actor_id   bigint NOT NULL,
    key        text NOT NULL,
    org_id     bigint NOT NULL,
    project_id bigint NOT NULL,
    operation  smallint NOT NULL,         -- 1 create card, 2 comment, 3 transition
    card_id    bigint NOT NULL,           -- the card created, moved or commented on
    subject_id bigint NOT NULL,           -- the card for operations 1 and 3, the comment for 2
    created_at timestamptz NOT NULL,
    PRIMARY KEY (actor_kind, actor_id, key)
);

CREATE TABLE notes (
    id              bigint PRIMARY KEY,
    org_id          bigint NOT NULL,
    project_id      bigint NOT NULL,              -- org-wide notes live in the global project
    status          smallint NOT NULL, -- 10 active, -10 archived
    version         bigint NOT NULL,
    page_bytes      integer NOT NULL,             -- size of the note's page in note_pages; 0 when it has none
    created_by_kind smallint NOT NULL CHECK (created_by_kind IN (1, 2)),
    created_by_id   bigint NOT NULL,
    updated_by_kind smallint NOT NULL CHECK (updated_by_kind IN (1, 2)),
    updated_by_id   bigint NOT NULL,
    created_at      timestamptz NOT NULL,
    updated_at      timestamptz NOT NULL,
    slug            text NOT NULL,
    title           text NOT NULL,
    body            text NOT NULL
);
CREATE UNIQUE INDEX notes_project_slug_key ON notes (project_id, slug);
CREATE INDEX notes_project_recent_idx ON notes (project_id, updated_at DESC, id DESC);
CREATE INDEX notes_org_recent_idx ON notes (org_id, updated_at DESC, id DESC);
CREATE INDEX notes_search_idx ON notes USING gin (to_tsvector('english', title || ' ' || body));

-- The HTML page of a note, kept apart from notes for the reason card_pages is
-- kept apart from cards.
CREATE TABLE note_pages (
    note_id bigint PRIMARY KEY,
    html    text NOT NULL,
    text    text NOT NULL                         -- visible text, at most 256 KiB (tsvector size limit)
);
CREATE INDEX note_pages_search_idx ON note_pages USING gin (to_tsvector('english', text));

-- The title, body and page a note had before an edit replaced them.
CREATE TABLE note_revisions (
    id              bigint PRIMARY KEY,
    note_id         bigint NOT NULL,
    version         bigint NOT NULL,
    updated_by_kind smallint NOT NULL CHECK (updated_by_kind IN (1, 2)),
    updated_by_id   bigint NOT NULL,
    title           text NOT NULL,
    body            text NOT NULL,
    page            text                          -- null: this version's page is the same as the next newer version's (the edit after it left the page alone); '': it had no page; otherwise its page
);
CREATE UNIQUE INDEX note_revisions_key ON note_revisions (note_id, version);

-- The title, body and page a card had before an edit replaced them, and who
-- replaced them.
CREATE TABLE card_revisions (
    id              bigint PRIMARY KEY,
    card_id         bigint NOT NULL,
    version         bigint NOT NULL,
    updated_by_kind smallint NOT NULL CHECK (updated_by_kind IN (1, 2)),
    updated_by_id   bigint NOT NULL,
    created_at      timestamptz NOT NULL,
    title           text NOT NULL,
    body            text NOT NULL,
    page            text                          -- null: this version's page is the same as the next newer version's (the edit after it left the page alone); '': it had no page; otherwise its page
);
CREATE UNIQUE INDEX card_revisions_key ON card_revisions (card_id, version);

-- Resolved [[...]] references, for backlinks. Ids are unique across tables,
-- so the types are informational only.
CREATE TABLE refs (
    source_type smallint NOT NULL,                -- 1 card, 3 note (2 is retired, not reused)
    source_id   bigint NOT NULL,
    target_type smallint NOT NULL,
    target_id   bigint NOT NULL,
    PRIMARY KEY (source_id, target_id)
);
CREATE INDEX refs_target_idx ON refs (target_id);

-- Append-only log. Readers page in (xid, id) order and only below the oldest
-- transaction still open, so an event that commits late is never left behind
-- a cursor; clients name a position by (xid, id). No summary or names:
-- clients render from the payload, which carries the subject's title at the
-- time.
CREATE TABLE events (
    org_id         bigint NOT NULL,
    id             bigint NOT NULL,
    project_id     bigint,                        -- null for org-level events
    xid            xid8 NOT NULL,
    type           smallint NOT NULL,
    actor_kind     smallint NOT NULL CHECK (actor_kind IN (1, 2)),
    actor_id       bigint NOT NULL,
    actor_session  text NOT NULL,                 -- the request's session label; empty when the client sent none
    subject_type   smallint NOT NULL,             -- 1 card, 3 note, 4 project, 5 agent, 6 membership, 7 token, 8 lock
    subject_id     bigint NOT NULL,
    subject_number bigint NOT NULL,
    payload        jsonb,
    PRIMARY KEY (org_id, id)
);
CREATE INDEX events_subject_idx ON events (subject_id, id DESC);
-- Feed order: every reader pages by (xid, id) under the xmin gate (see queries/events.sql).
CREATE INDEX events_feed_idx ON events (org_id, xid, id);

-- +goose Down

DROP TABLE events;
DROP TABLE refs;
DROP TABLE card_revisions;
DROP TABLE note_revisions;
DROP TABLE note_pages;
DROP TABLE notes;
DROP TABLE request_keys;
DROP TABLE card_reads;
DROP TABLE comments;
DROP TABLE card_links;
DROP TABLE locks;
DROP TABLE card_subscriptions;
DROP TABLE claims;
DROP TABLE card_pages;
DROP TABLE cards;
DROP TABLE agent_join_rules;
DROP TABLE agent_session_grants;
DROP TABLE agent_sessions;
DROP TABLE project_members;
DROP TABLE projects;
DROP TABLE tokens;
DROP TABLE agents;
DROP TABLE memberships;
DROP TABLE identities;
DROP TABLE users;
DROP TABLE orgs;
